70:fn open_controlled(
71:    path: &Path,
72:    directory: bool,
73:    guest_boundary: Option<&Path>,
74:    mapped_parent: Option<(&Path, u64)>,
75:) -> Result<File> {
76:    ensure!(
77:        canonical(path.to_str().context("physical path encoding")?),
78:        "unsafe physical path"
79:    );
80:    let root = CString::new("/")?;
81:    // SAFETY: NUL-terminated paths, owned descriptors; no filesystem mutation.
82:    let fd = unsafe {
83:        libc::open(
84:            root.as_ptr(),
85:            libc::O_RDONLY | libc::O_DIRECTORY | libc::O_CLOEXEC | libc::O_NOFOLLOW,
86:        )
87:    };
88:    ensure!(fd >= 0, "open physical path root");
89:    // SAFETY: successful open returned a fresh descriptor.
90:    let mut current = unsafe { File::from_raw_fd(fd) };
91:    let components: Vec<_> = path
92:        .components()
93:        .filter_map(|p| {
94:            if let Component::Normal(p) = p {
95:                Some(p)
96:            } else {
97:                None
98:            }
99:        })
100:        .collect();
101:    let mut prefix = PathBuf::from("/");
102:    for (index, component) in components.iter().enumerate() {
103:        prefix.push(component);
104:        let name = CString::new(component.as_encoded_bytes())?;
105:        let flags = libc::O_RDONLY
106:            | libc::O_CLOEXEC
107:            | libc::O_NOFOLLOW
108:            | if index + 1 < components.len() || directory {
109:                libc::O_DIRECTORY
110:            } else {
111:                0
112:            };
113:        // SAFETY: valid held parent FD and NUL-terminated component.
114:        let next = unsafe { libc::openat(current.as_raw_fd(), name.as_ptr(), flags) };
115:        ensure!(next >= 0, "physical path absent or contains a symlink");
116:        // SAFETY: successful openat returned a fresh descriptor.
117:        current = unsafe { File::from_raw_fd(next) };
118:        if index + 1 < components.len() || directory {
